using EEMS.Modules.Elections.Infrastructure;
using EEMS.Modules.Finance.Domain;
using EEMS.Modules.Finance.Infrastructure;
using EEMS.SharedKernel.Tenancy;
using Microsoft.EntityFrameworkCore;

namespace EEMS.Api.Finance;
public sealed class FinanceOperationsService(FinanceDbContext db,ElectionsDbContext elections,ITenantContext tenant)
{
 public async Task<FinanceWorkspace?> GetAsync(Guid electionId,CancellationToken ct){if(!await ElectionExists(electionId,ct))return null;var budgets=await db.Budgets.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId).OrderByDescending(x=>x.CreatedAtUtc).ToListAsync(ct);var ids=budgets.Select(x=>x.Id).ToArray();var lines=await db.BudgetLines.Where(x=>x.TenantId==tenant.TenantId&&ids.Contains(x.BudgetId)).ToListAsync(ct);var lineIds=lines.Select(x=>x.Id).ToArray();var expenses=await db.Expenses.Where(x=>x.TenantId==tenant.TenantId&&lineIds.Contains(x.BudgetLineId)).OrderByDescending(x=>x.CreatedAtUtc).ToListAsync(ct);var expenseIds=expenses.Select(x=>x.Id).ToArray();var paid=await db.Payments.Where(x=>x.TenantId==tenant.TenantId&&expenseIds.Contains(x.ExpenseId)).GroupBy(x=>x.ExpenseId).Select(x=>new{x.Key,Amount=x.Sum(y=>y.Amount)}).ToDictionaryAsync(x=>x.Key,x=>x.Amount,ct);return new(await db.ExpenseStates.Where(x=>x.IsActive).OrderBy(x=>x.Id).Select(x=>new ExpenseStateSummary(x.Id,x.Code,x.Name,x.IsApproved,x.IsTerminal)).ToListAsync(ct),await db.Vendors.Where(x=>x.TenantId==tenant.TenantId&&x.IsActive).OrderBy(x=>x.Name).Select(x=>new VendorSummary(x.Id,x.Name,x.RegistrationNumber)).ToListAsync(ct),budgets.Select(b=>new BudgetSummary(b.Id,b.Name,b.Currency,b.CreatedAtUtc,lines.Where(l=>l.BudgetId==b.Id).Select(l=>new BudgetLineSummary(l.Id,l.Category,l.AllocatedAmount,expenses.Where(e=>e.BudgetLineId==l.Id).Sum(e=>e.Amount))).ToArray())).ToArray(),expenses.Select(x=>new ExpenseSummary(x.Id,x.BudgetLineId,x.VendorId,x.SubmittedByUserId,x.StateId,x.InvoiceNumber,x.Amount,x.ExpenseDate,x.CreatedAtUtc,x.Version,paid.GetValueOrDefault(x.Id))).ToArray());}
 public async Task<BudgetSummary?> CreateBudget(Guid electionId,string name,string currency,CancellationToken ct){if(!await ElectionExists(electionId,ct)||await db.Budgets.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId&&x.Name==name.Trim(),ct))return null;var x=Budget.Create(tenant.TenantId,electionId,name,currency);db.Budgets.Add(x);await db.SaveChangesAsync(ct);return new(x.Id,x.Name,x.Currency,x.CreatedAtUtc,[]);}
 public async Task<BudgetLineSummary?> AddLine(Guid electionId,Guid budgetId,string category,decimal amount,CancellationToken ct){var ok=await db.Budgets.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId&&x.Id==budgetId,ct);if(!ok||await db.BudgetLines.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.BudgetId==budgetId&&x.Category==category.Trim(),ct))return null;var x=BudgetLine.Create(tenant.TenantId,budgetId,category,amount);db.BudgetLines.Add(x);await db.SaveChangesAsync(ct);return new(x.Id,x.Category,x.AllocatedAmount,0);}
 public async Task<VendorSummary?> AddVendor(string name,string registration,CancellationToken ct){if(await db.Vendors.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.RegistrationNumber==registration.Trim(),ct))return null;var x=Vendor.Create(tenant.TenantId,name,registration);db.Vendors.Add(x);await db.SaveChangesAsync(ct);return new(x.Id,x.Name,x.RegistrationNumber);}
 public async Task<ExpenseSummary?> Submit(Guid electionId,Guid userId,SubmitExpense command,CancellationToken ct){var line=await(from l in db.BudgetLines join b in db.Budgets on l.BudgetId equals b.Id where l.TenantId==tenant.TenantId&&l.Id==command.BudgetLineId&&b.ElectionId==electionId select l).SingleOrDefaultAsync(ct);var state=await db.ExpenseStates.Where(x=>x.IsActive&&!x.IsTerminal).OrderBy(x=>x.Id).FirstOrDefaultAsync(ct);var spent=line is null?0:await db.Expenses.Where(x=>x.TenantId==tenant.TenantId&&x.BudgetLineId==line.Id).SumAsync(x=>x.Amount,ct);if(line is null||state is null||command.Amount<=0||spent+command.Amount>line.AllocatedAmount||(command.VendorId.HasValue&&!await db.Vendors.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.Id==command.VendorId&&x.IsActive,ct)))return null;var x=Expense.Create(tenant.TenantId,line.Id,command.VendorId,userId,state.Id,command.InvoiceNumber,command.Amount,command.ExpenseDate);db.Expenses.Add(x);await db.SaveChangesAsync(ct);return Summary(x,0);}
 public async Task<ExpenseSummary?> Decide(Guid electionId,Guid expenseId,Guid checker,short stateId,int expectedVersion,string note,CancellationToken ct){var x=await ElectionExpense(electionId,expenseId,ct);var state=await db.ExpenseStates.SingleOrDefaultAsync(s=>s.Id==stateId&&s.IsActive&&s.IsTerminal,ct);if(x is null||state is null||x.Version!=expectedVersion||x.SubmittedByUserId==checker)return null;db.Approvals.Add(ExpenseApproval.Record(tenant.TenantId,x.Id,x.SubmittedByUserId,checker,state.Id,note));x.MoveTo(state.Id);await db.SaveChangesAsync(ct);return Summary(x,await Paid(x.Id,ct));}
 public async Task<ExpenseSummary?> Pay(Guid electionId,Guid expenseId,Guid userId,decimal amount,string reference,CancellationToken ct){var x=await ElectionExpense(electionId,expenseId,ct);var approved=x is null?null:await db.ExpenseStates.SingleAsync(s=>s.Id==x.StateId,ct);var paid=x is null?0:await Paid(x.Id,ct);if(x is null||approved is null||!approved.IsApproved||amount<=0||paid+amount>x.Amount)return null;db.Payments.Add(Payment.Record(tenant.TenantId,x.Id,userId,amount,reference,DateTimeOffset.UtcNow));await db.SaveChangesAsync(ct);return Summary(x,paid+amount);}
 private Task<bool> ElectionExists(Guid id,CancellationToken ct)=>elections.Elections.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.Id==id,ct);private async Task<Expense?> ElectionExpense(Guid electionId,Guid expenseId,CancellationToken ct)=>await(from e in db.Expenses join l in db.BudgetLines on e.BudgetLineId equals l.Id join b in db.Budgets on l.BudgetId equals b.Id where e.TenantId==tenant.TenantId&&e.Id==expenseId&&b.ElectionId==electionId select e).SingleOrDefaultAsync(ct);private Task<decimal> Paid(Guid id,CancellationToken ct)=>db.Payments.Where(x=>x.TenantId==tenant.TenantId&&x.ExpenseId==id).SumAsync(x=>x.Amount,ct);private static ExpenseSummary Summary(Expense x,decimal paid)=>new(x.Id,x.BudgetLineId,x.VendorId,x.SubmittedByUserId,x.StateId,x.InvoiceNumber,x.Amount,x.ExpenseDate,x.CreatedAtUtc,x.Version,paid);
}
public sealed record FinanceWorkspace(IReadOnlyList<ExpenseStateSummary> States,IReadOnlyList<VendorSummary> Vendors,IReadOnlyList<BudgetSummary> Budgets,IReadOnlyList<ExpenseSummary> Expenses);public sealed record ExpenseStateSummary(short Id,string Code,string Name,bool IsApproved,bool IsTerminal);public sealed record VendorSummary(Guid VendorId,string Name,string RegistrationNumber);public sealed record BudgetSummary(Guid BudgetId,string Name,string Currency,DateTimeOffset CreatedAtUtc,IReadOnlyList<BudgetLineSummary> Lines);public sealed record BudgetLineSummary(Guid BudgetLineId,string Category,decimal AllocatedAmount,decimal CommittedAmount);public sealed record ExpenseSummary(Guid ExpenseId,Guid BudgetLineId,Guid? VendorId,Guid SubmittedByUserId,short StateId,string InvoiceNumber,decimal Amount,DateOnly ExpenseDate,DateTimeOffset CreatedAtUtc,int Version,decimal PaidAmount);public sealed record SubmitExpense(Guid BudgetLineId,Guid? VendorId,string InvoiceNumber,decimal Amount,DateOnly ExpenseDate);
